  'Reps up to': '최대 횟수',
  'No automatic progression': '자동 증가 없음',
  'The next regular target continues from the last included workout.': '다음 일반 목표는 마지막으로 포함된 운동에서 이어집니다.',
  'Deload routine': '디로딩 루틴',
  'Its workouts do not count toward progression. They still show in history and statistics.': '이 루틴의 운동은 점진적 증가에 반영되지 않습니다. 기록과 통계에는 계속 표시됩니다.',
  'A deload routine opens at the numbers set here, so the progression above does not apply to it.': '디로딩 루틴은 여기서 정한 수치로 시작하므로 위의 점진적 증가가 적용되지 않습니다.',
  'Linear progression': '선형 증가',
  'Greyskull LP': 'Greyskull LP',
  'Double progression': '이중 점증',
  'Add time': '시간 늘리기',
  'Targets stay where you set them.': '목표는 설정한 그대로 유지됩니다.',
  'Hit every rep in every set and the weight goes up. Repeated misses trigger a deload.': '모든 세트에서 목표 횟수를 채우면 무게가 올라갑니다. 반복해서 실패하면 디로드가 걸립니다.',
  'Two straight sets plus a final set taken to failure. Beat the target on that set and the weight goes up (twice as much if you double the reps). One failure resets 10 %.': '일반 두 세트에 마지막 한 세트는 실패 지점까지. 그 세트에서 목표를 넘기면 무게가 올라요(횟수를 두 배로 하면 두 배로). 한 번 실패하면 10 % 되돌려요.',
  'Work up through a rep range at the same weight. Reach the top of the range in every set and the weight goes up, reps back to the bottom.': '같은 무게에서 반복 범위를 올려 갑니다. 모든 세트에서 상한에 도달하면 무게가 오르고 횟수는 하한으로 돌아갑니다.',
  'Hold every set for the full duration and the target goes up.': '모든 세트를 목표 시간만큼 버티면 목표가 올라갑니다.',
  'Nothing logged yet, so this session sets the baseline.': '아직 기록이 없어서 이번 세션이 기준이 돼요.',
  'Held every set for the full time. Target goes up by {0}s.': '모든 세트를 끝까지 버텼어요. 목표가 {0}초 늘어나요.',
  'Short {0} sessions in a row. Back off to {1}s and build up again.': '{0}회 연속으로 시간이 모자랐어요. {1}초로 낮추고 다시 쌓아 가요.',
  'Came up short last time. Same target again.': '지난번엔 조금 모자랐어요. 같은 목표로 한 번 더.',
  'Top of the rep range in every set. {0} {1} more, back to {2} reps.': '모든 세트에서 범위 상한 도달. {0} {1} 올리고 횟수는 {2}회로.',
  'Stuck for {0} sessions. Deload to {1} {2}.': '{0}번의 세션 동안 정체. {1} {2}(으)로 디로드.',
  'Same weight, aim for {0} reps this time.': '같은 무게로, 이번엔 {0}회를 노려 보세요.',
  'Last set hit {0} reps, twice the target! Take a double jump of {1} {2}.': '마지막 세트 {0}회, 목표의 두 배! {1} {2}만큼 두 배로 올려요.',
  'Every rep last time. {0} {1} more.': '지난번 모든 반복 성공. {0} {1} 증가.',
  'Every rep last time. {0} {1} less help.': '지난번 모든 반복 성공. 보조 {0} {1} 줄이기.',
  'Top of the rep range in every set. {0} {1} less help, back to {2} reps.': '모든 세트에서 반복 범위 상단. 보조 {0} {1} 줄이고 {2}회로 돌아가기.',
  'Missed reps. {0} {1} of help while you build back up.': '반복 미달. 다시 올라올 때까지 보조 {0} {1}.',
  'Stuck for {0} sessions. Back to {1} {2} of help, then build up again.': '{0}회 정체. 보조 {1} {2}(으)로 돌아가 다시 쌓기.',
  'Missed reps {0} sessions running. Reset to {1} {2} and work back up.': '{0}회 연속 목표 횟수 미달. {1} {2}(으)로 되돌리고 다시 올라가세요.',
  'Missed reps. Reset to {0} {1} and work back up.': '목표 횟수 미달. {0} {1}(으)로 되돌리고 다시 올라가세요.',
  'Missed reps last time. Same weight again ({0} of {1} to go).': '지난번 목표 횟수 미달. 같은 무게로 한 번 더({1}회 중 {0}회 남음).',
  'Bodyweight: every rep last time, so go for {0} this time.': '맨몸 운동: 지난번 모든 반복 성공, 이번엔 {0}회를 노려 보세요.',
  'Bodyweight: same target again until every set is clean.': '맨몸 운동: 모든 세트가 깔끔해질 때까지 같은 목표로.',

  // --- effort per set (RIR / RPE) ---
  '{0} sets bring an {1} with them. Switch on Effort per set in Settings to see it.': '{0}개 세트에 {1}이(가) 함께 들어 있어요. 설정에서 ‘세트당 강도’를 켜면 보여요.',
  '{0} sets bring an {1} with them.': '{0}개 세트에 {1}이(가) 함께 들어 있습니다.',
  'RIR': 'RIR',
  'RPE': 'RPE',
  'Effort per set': '세트당 강도',
  'What are RIR and RPE?': 'RIR과 RPE란?',
  'How hard a set was, logged next to weight and reps. Two scales for the same judgement, counted from opposite ends.': '세트가 얼마나 힘들었는지를 무게·횟수 옆에 함께 기록합니다. 같은 판단을 양쪽 끝에서 세는 두 가지 척도입니다.',
  'How it felt': '느낌',
  'Nothing left, went to failure': '남은 게 없음, 실패 지점까지',
  'One more rep in the tank': '한 개 더 남았음',
  'Two more reps': '두 개 더 남았음',
  'Three more reps': '세 개 더 남았음',
  'Easy, warm-up territory': '가뿐함, 웜업 구간',
  'Maybe half a rep left': '반 개 정도 더 남았을지도',
  'How hard was that set?': '이 세트는 얼마나 힘들었나요?',
  'Tap how many reps you had left, or type an exact {0}.': '몇 개 더 할 수 있었는지 탭하거나 정확한 {0} 값을 입력하세요.',
  'Exact {0}': '정확한 {0}',
  'Clear rating': '평가 지우기',
  'RIR counts the reps you left in the tank; RPE reads the same effort off a 10-point scale, so RPE ≈ 10 − RIR. Pick whichever you already think in.': 'RIR은 남겨 둔 횟수를 세고, RPE는 같은 노력을 10점 척도로 읽어요. 그래서 RPE ≈ 10 − RIR. 평소에 생각하던 쪽을 고르세요.',
  'The highlighted row is where most working sets land. Sets you have already logged keep their own scale, and nothing else reads the value, so progression and estimated 1RM are unaffected.': '강조된 줄은 대부분의 본세트가 들어가는 구간이에요. 이미 기록한 세트는 원래 척도를 유지하고, 이 값을 읽는 곳도 없어서 프로그레션과 예상 1RM은 영향을 받지 않아요.',
  // --- effort in the stats ---
  'Effort': '강도',
  'how close to failure': '실패 지점에 얼마나 가까운지',
  'by hard sets': '힘든 세트 기준',
