  'no hard sets': '힘든 세트 없음',
  'No hard sets in this period': '이 기간에 힘든 세트 없음',
  'Every muscle group got at least one hard set in this period.': '이 기간에 모든 근육군이 최소 한 세트는 힘들게 훈련했습니다.',
  'No rated sets in this period.': '이 기간에 평가된 세트가 없습니다.',
  'average effort': '평균 강도',
  'at {0} {1} or harder': '{0} {1} 이상',
  '{0} of {1} finished sets rated': '완료한 {1}세트 중 {0}세트 평가됨',
  'Week by week': '주별 변화',
  'Where the sets land': '세트가 몰리는 곳',
  'Most working sets belong close to failure, not at it. Half at the floor and half at the top still average out to a healthy-looking middle.': '대부분의 본세트는 실패 지점에 가까워야 하지, 실패 지점이면 안 돼요. 절반은 바닥, 절반은 꼭대기여도 평균은 그럴듯해 보이거든요.',
  'Average effort per workout': '운동당 평균 강도',
  'A fuller dot means less left in the tank. The same weight at a lower {0} is progress the line alone doesn’t show.': '점이 꽉 찰수록 남은 여력이 적다는 뜻이에요. 같은 무게를 더 낮은 {0}(으)로 들었다면, 선만 봐서는 안 보이는 발전이에요.',

  // --- bodyweight & per side ---
  'Bodyweight': '맨몸 운동',
  'No weight to enter. Just log the reps.': '입력할 무게 없음. 횟수만 기록하세요.',
