  'Runs on your openGym server': '내 openGym 서버에서 실행',
  'Save and use the Coach': '저장하고 코치 사용',
  'The Coach is already thinking about your training.': '코치가 이미 당신의 훈련을 검토 중입니다.',
  'The Coach is taking a breather. You’ve used today’s {0} runs on this phone.': '코치가 잠깐 숨 돌리는 중이에요. 이 휴대폰에서 오늘의 {0}회 실행을 모두 썼어요.',
  'The Coach isn’t set up on this phone.': '이 휴대폰에는 코치가 설정되어 있지 않습니다.',
  'The Coach needs your go-ahead first.': '먼저 코치에게 동의가 필요합니다.',
  'The key is stored in this phone’s secure storage and never leaves it except to call the provider.': '키는 이 휴대폰의 보안 저장소에 보관되며 제공자를 호출할 때 외에는 절대 밖으로 나가지 않습니다.',
  'This phone calls the provider directly with your key. Every request is charged to your account.': '이 휴대폰이 당신의 키로 제공자를 직접 호출합니다. 모든 요청은 당신의 계정에 청구됩니다.',
  'Turn the Coach off on this phone': '이 휴대폰에서 코치 끄기',
  'Use my self-hosted openGym': '내 자체 호스팅 openGym 사용',
  'What leaves this phone': '이 휴대폰에서 나가는 것',
  'Your server has no Coach enabled. Ask its admin, or bring your own key below.': '서버에 코치가 활성화되어 있지 않아요. 관리자에게 문의하거나 아래에서 내 키를 사용하세요.',
  'Your server runs the Coach with whatever provider its admin set up. Nothing new leaves this phone beyond what already syncs.': '서버가 관리자가 설정한 제공자로 코치를 실행합니다. 이미 동기화되는 것 외에는 이 휴대폰에서 새로 나가는 것이 없습니다.',
  'Loading the exercise catalogue…': '운동 카탈로그 불러오는 중…',
  'Checking the endpoint…': '엔드포인트 확인 중…',

  // --- AI Coach chat ---
  'A local model can take longer.': '로컬 모델은 더 오래 걸릴 수 있습니다.',
  'All optional. The more the Coach knows, the less it guesses.': '모두 선택 사항입니다. 코치가 많이 알수록 추측이 줄어듭니다.',
  'Almost there': '거의 다 됐어요',
  'Avoid: {0}': '피할 것: {0}',
  'Before we start': '시작하기 전에',
  'Building your plan…': '계획을 만드는 중…',
  'Discarded. Tell me what was off and I will build a different one.': '폐기했습니다. 무엇이 맞지 않았는지 알려주시면 다른 계획을 만들게요.',
  'Done! Your plan is back to how it was before my last changes.': '완료! 계획이 제 마지막 변경 전으로 돌아갔어요.',
  'Edit my answers': '내 답변 수정',
  'Start a new plan': '새 계획 시작',
  'A fresh plan from your answers; your workouts stay': '답변을 바탕으로 새 계획을 만듭니다. 운동 기록은 그대로 남습니다',
  'Build me a fresh plan from my answers.': '내 답변을 바탕으로 새 계획을 만들어 줘.',
  'Experience': '경험',
  'Goal, days, equipment, limits': '목표, 요일, 장비, 제한',
  'Have a look at my training and tell me what you would change.': '내 훈련을 보고 무엇을 바꿀지 알려주세요.',
  'Here is what I am working with:': '제 상황은 이렇습니다:',
  'Hi, I’m your Coach. I build your plan from your answers and adjust it from what you actually log. Nothing changes until you say so.': '안녕하세요, 당신의 코치예요. 답변을 바탕으로 계획을 만들고 실제 기록에 맞춰 조정해요. 당신이 말하기 전에는 아무것도 바뀌지 않아요.',
  'I looked through everything and there is nothing I would change right now. Keep it up, and ask me again after a few more sessions.': '전부 살펴봤는데 지금은 바꿀 게 없어요. 이대로 계속하고, 몇 번 더 운동한 뒤 다시 물어보세요.',
  'I understand, let’s go': '알겠어요, 시작해요',
  'Imported! {0} routines are in your plan and your week is set. See you at the next session.': '가져왔어요! 루틴 {0}개가 계획에 들어갔고 주간 일정도 잡혔어요. 다음 세션에서 봐요.',
  'Imported! {0} routines are in your plan. Your week is unchanged; schedule them whenever you like.': '가져왔어요! 루틴 {0}개가 계획에 들어갔어요. 주간 일정은 그대로이니 원할 때 배정하세요.',
  'It designs your plan from a few answers and adjusts it from what you actually log. It never changes anything without your say-so, and you can undo every change.': '몇 가지 답변으로 계획을 설계하고 실제 기록에 따라 조정합니다. 동의 없이는 아무것도 바꾸지 않으며, 모든 변경을 되돌릴 수 있습니다.',
  'Routines, exercises, sets and reps, your weekly schedule and progression settings.': '루틴, 운동, 세트와 횟수, 주간 일정과 점진적 증가 설정.',
  'Your logged training': '내 운동 기록',
  'Sets you logged in the review window: weights, reps, times, effort ratings, how long sessions took, and your session notes.': '검토 기간에 기록한 세트: 무게, 횟수, 시간, 강도 평가, 세션 소요 시간, 그리고 운동 메모.',
  'Weigh-ins from the same window, and your goal weight if you set one.': '같은 기간의 체중 기록, 그리고 설정했다면 목표 체중.',
  'What you tell the Coach': '코치에게 알려 준 내용',
  'Your intake answers, including any limitations or injuries you describe.': '시작 질문에 대한 답변. 설명한 제약 사항이나 부상도 포함됩니다.',
  'A few preferences': '몇 가지 설정',
  'Your unit, your language and which effort scale you log.': '단위, 언어, 그리고 강도를 기록하는 척도.',
  'Likes: {0}': '좋아함: {0}',
  'Limits': '제한',
  'Limits: {0}': '제한: {0}',
  'Not quite right? Say what to change below and I will revise the whole plan.': '마음에 안 드나요? 아래에 바꿀 점을 말해주시면 계획 전체를 수정할게요.',
  'Pick one to continue.': '계속하려면 하나를 선택하세요.',
  'Pick what you will actually keep, not the best week you can imagine.': '상상 속 최고의 한 주가 아니라 실제로 지킬 수 있는 만큼 고르세요.',
