  'Sent to {0}, running on this server under the instance owner’s account.': '이 서버에서 인스턴스 소유자 계정으로 실행되는 {0}에 전송됩니다.',
  'Session length': '세션 길이',
  'Sets the pace of progression, and how much the Coach assumes you know.': '진행 속도와 코치가 당신이 얼마나 알고 있다고 가정할지를 정합니다.',
  'Suggestions': '제안',
