  'Imported! {0} routines are in your plan and your rotation starts over with them. See you at the next session.': '가져왔어요! 루틴 {0}개가 계획에 들어갔고 로테이션도 이 루틴들로 다시 시작해요. 다음 세션에서 봐요.',
