  'Change exercise': '운동 변경',
  'Use default exercise': '기본 운동 사용',
  'Custom': '사용자 지정',
  'Log your body weight to score this lift.': '이 운동을 평가하려면 체중을 기록하세요.',
  'Log the anchor lift to score this one.': '이 운동을 평가하려면 기준 운동을 기록하세요.',
  'Not scored': '평가 안 됨',
  'The server cannot be reached': '서버에 연결할 수 없음',
  'Your server can’t be reached. Your changes are saved on this device and sync once it answers again.': '서버에 연결할 수 없습니다. 변경 사항은 이 기기에 저장되며 서버가 다시 응답하면 동기화됩니다.',
  'Your server can’t be reached. Showing the last copy synced with it.': '서버에 연결할 수 없습니다. 서버와 마지막으로 동기화된 사본을 표시합니다.',
  'Server address unknown': '서버 주소를 알 수 없음',
  'Pair again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': '다시 페어링하거나 먼저 백업을 내보내세요. 그래도 계속하면 이 기기가 이 계정으로 이 서버에 다시 연결될 때까지 변경 사항의 사본이 이 기기에 보관됩니다. 그때 다시 추가됩니다.',
  'Sign in again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': '다시 로그인하거나 먼저 백업을 내보내세요. 그래도 계속하면 이 기기가 이 계정으로 이 서버에 다시 연결될 때까지 변경 사항의 사본이 이 기기에 보관됩니다. 그때 다시 추가됩니다.',
  '{0} set · {1} work': '{0} 세트 · {1} 작업',
  'Every exercise in this workout': '이번 세션의 모든 운동',
  'No sets are left in this workout, so there is nothing to save. Delete it from your history?': '이 운동에 남은 세트가 없어 저장할 내용이 없습니다. 기록에서 삭제할까요?',
  // --- a custom exercise's own photo, GIF or video, and its link ---
  'Photo, GIF or video': '사진, GIF 또는 동영상',
  'Optional. A picture makes it easier to spot in a list.': '선택 사항. 사진이 있으면 목록에서 더 쉽게 찾을 수 있어요.',
  'Add': '추가',
  'Change': '변경',
  'Video or guide link (optional)': '동영상 또는 가이드 링크 (선택)',
