  'Sets, routines and the loop: left removes, right copies': '세트, 루틴, 순환: 왼쪽은 제거, 오른쪽은 복사',
  'Psst: swipe a set. Left deletes, right copies.': '쉿: 세트를 밀어 보세요. 왼쪽은 삭제, 오른쪽은 복사.',
