  'Withdraw': '철회',
  'Withdrawn. The Coach will ask before it sends anything again.': '철회했어요. 다시 보내기 전에 코치가 물어볼 거예요.',
  'Your answers to the Coach: goal, days, equipment, limits and injuries': '코치에게 한 답변: 목표, 요일, 장비, 제한 사항과 부상',
