  'Your training on paper: totals, charts, new bests and every set. Frame it, print it or send it to your coach.': '종이에 담은 내 운동: 합계, 차트, 새 기록, 모든 세트. 액자에 걸거나 인쇄하거나 코치에게 보내 보세요.',
