  "Programmes and sharing": "프로그램과 공유",
  "Programmes, starter plans and sharing a plan with a friend live behind this button.": "프로그램, 시작 계획, 친구와 계획 공유는 이 버튼 뒤에 있어요.",
  "Records": "기록",
  "Schedule says when, Routines says what. Build your own or grab a starter plan.": "일정은 언제, 루틴은 무엇. 직접 만들거나 시작 계획을 가져오세요.",
  "Search thousands of exercises in your language. Star your favourites and they float to the top.": "내 언어로 수천 가지 운동. 즐겨찾기에 별을 달면 맨 위로 올라와요.",
  "See which muscles got the work and which still need rest. Tap one for details.": "어떤 근육이 일했고 어떤 근육이 아직 쉬어야 하는지 보세요. 하나를 누르면 자세히 나와요.",
