  "Swipe a set": "세트 밀기",
  "Swipe a set sideways to copy or remove it. Its number opens even more.": "세트를 옆으로 밀어 복사하거나 지우세요. 세트 번호를 누르면 더 많아요.",
  "The big Start button": "커다란 시작 버튼",
  "The little body shows what each day works, so leg day can’t hide.": "작은 몸이 날마다 어디를 쓰는지 보여 줘요. 하체 날은 숨을 수 없어요.",
  "The rest timer starts by itself. Add time, or skip it if you feel heroic.": "휴식은 저절로 시작돼요. 시간을 더하거나, 영웅 기분이면 건너뛰세요.",
  "The ⋯ menu": "⋯ 메뉴",
  "Theme, accent colour and what Home shows.": "테마, 강조 색상, 홈에 보일 것.",
  "This one is pretend, nothing gets saved. Each row is a set: weight, then reps. Tap a number to change it.": "이건 연습이라 아무것도 저장되지 않아요. 한 줄이 한 세트예요: 무게, 그다음 횟수. 숫자를 눌러 바꾸세요.",
  "Tick it off": "체크하기",
  "Today at a glance": "오늘 한눈에",
  "Today’s session lives here. One tap and you’re lifting. On a rest day it says so, no guilt trip.": "오늘 세션이 여기 있어요. 한 번 누르면 바로 운동. 휴식일엔 휴식일이라고 해요, 죄책감 없이.",
  "Train on fixed weekdays, or run your routines in a loop where the next one waits for you.": "정해진 요일에 운동하거나, 루틴을 순환시켜 다음 루틴이 기다리게 하세요.",
  "Want a 1-minute tour?": "1분 둘러보기 할까요?",
  "Week or rotation": "주간 또는 로테이션",
  "We’ll point at the good bits on the real screens. Bail out anytime.": "진짜 화면에서 좋은 것만 짚어 드릴게요. 언제든 그만둘 수 있어요.",
  "Workout settings, layouts, notes and extra exercises hide in here.": "운동 설정, 레이아웃, 메모, 운동 추가가 여기 숨어 있어요.",
  "Workouts, streaks and everything you’ve lifted. It fills up as you train.": "운동, 연속 기록, 지금까지 든 모든 것. 운동할수록 채워져요.",
  "You stopped halfway. Want to see the rest?": "중간에 멈추셨어요. 나머지도 볼까요?",
  "Your data, your backups": "내 데이터, 내 백업",
