  "One more week with a workout earns a freeze.": "운동한 주가 한 번 더 있으면 동결권을 받아요.",
  "{0} more weeks with a workout earn a freeze.": "운동한 주가 {0}번 더 있으면 동결권을 받아요.",
  "Watch on YouTube": "YouTube에서 보기",
