  // --- Your year in openGym (lib/wrapped-cards.js, components/Wrapped.jsx) ---
  "Mostly in the morning. The early bird gets the barbell.": "주로 아침에 했어요. 일찍 일어나는 새가 바벨을 잡죠.",
  "Mostly around lunch. Who needs a lunch break anyway?": "주로 점심 무렵에 했어요. 점심시간은 원래 운동하라고 있는 거죠?",
  "Mostly in the afternoon. The sweet spot.": "주로 오후에 했어요. 딱 좋은 타이밍.",
  "Mostly in the evening. Work, then work out.": "주로 저녁에 했어요. 일 끝나고, 운동 시작.",
  "Mostly late at night. The gym is all yours.": "주로 늦은 밤에 했어요. 헬스장 전세 낸 기분.",
  "Early bird": "아침형 인간",
  "Most of your sessions started before 9. The sun was still catching up.": "운동 대부분을 9시 전에 시작했어요. 해보다 먼저 출근했네요.",
  "Night owl": "올빼미",
  "Most of your sessions started after 8 pm. The quiet gym is your gym.": "운동 대부분을 저녁 8시 이후에 시작했어요. 조용한 헬스장이 당신 구역이에요.",
  "Leg-day loyalist": "하체 충성파",
  "You never skipped leg day. Stairs fear you.": "하체 데이를 한 번도 안 빼먹었어요. 계단이 당신을 무서워해요.",
  "Clockwork": "시계처럼 정확",
  "Week after week after week. Your calendar knows your name.": "매주, 매주, 또 매주. 달력이 당신 이름을 외웠어요.",
  "Record breaker": "기록 파괴자",
  "So many new bests, your trophy shelf needs a trophy shelf.": "신기록이 너무 많아서 트로피 선반에도 트로피 선반이 필요해요.",
  "Weekend warrior": "주말 전사",
  "Saturdays and Sundays are for lifting. Brunch can wait.": "토요일과 일요일은 들어 올리는 날. 브런치는 나중에.",
  "Cardio comet": "유산소 혜성",
  "Your heart is in great shape. Literally.": "심장 상태 최고예요. 진짜로요.",
  "In it for the long haul": "오래가는 타입",
