  "In and out": "짧고 굵게",
  "Short, sharp sessions. Efficiency is your love language.": "짧고 날카로운 운동. 효율이 당신의 사랑의 언어예요.",
  "Explorer": "탐험가",
  "So many different exercises, boredom never stood a chance.": "운동 종류가 이렇게 다양하니 지루할 틈이 없었어요.",
  "Upper-body enthusiast": "상체 마니아",
  "Chest, shoulders, arms. The mirror approves.": "가슴, 어깨, 팔. 거울이 인정했어요.",
  "Steady and sure": "꾸준함 그 자체",
  "No drama, just showing up. That is how it is done.": "드라마 없이 그냥 나타났어요. 원래 그렇게 하는 거예요.",
  "Your year in openGym": "openGym에서 보낸 한 해",
  "Grab a shake. This one is all about you.": "셰이크 한 잔 챙기세요. 오늘의 주인공은 당신이에요.",
  "Tap to start": "탭해서 시작",
