  "Logged sets and your routine stay as they are. The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.": "기록한 세트와 루틴은 그대로입니다. 코치는 의사나 물리치료사가 아닙니다. 통증이 있다면 전문가에게 문의하세요.",
